package flagutil

import (
	"encoding/json"
	"strings"
)

// friendlyDescription rewrites generated help strings into something a user
// can act on. Only the exact generated placeholder strings are replaced; a
// real per-flag description carried in the spec is left untouched apart from
// its Markdown backticks (see below).
func friendlyDescription(desc string) string {
	// Speakeasy copies OpenAPI descriptions verbatim and ours use Markdown
	// backticks around field names ("the given Earn `venue`"). pflag treats
	// the first back-quoted word of a usage string as the flag's value type,
	// so --help showed "--action venue" instead of "--action string". Plain
	// text reads fine in a terminal, so drop the quotes.
	desc = strings.ReplaceAll(desc, "`", "")

	// The opaque string Speakeasy emits for number|string union flags. The
	// CLI-only spec transform turns every Decimal request field into a plain
	// string flag, so this only fires for a union that slipped past it; the
	// number branch of such a union rounds through float64, hence the advice
	// to quote.
	const numberOrString = "JSON value (one of: number | string)"
	if desc == numberOrString {
		return `Decimal amount; pass it as a JSON string to keep full precision (e.g. "1.5").`
	}
	return desc
}

// unquoteJSONString returns the contents of val when it is a complete JSON
// string literal (the two characters `"USDC"` around the value included) and
// val unchanged otherwise. Earlier builds needed `--chain '"base"'` and
// documented `--amount '"0.5"'` as the way to keep an amount exact, so those
// quotes still show up in scripts and agent prompts; sent literally they turn
// into a 422 ("Unknown token symbol", "Input should be a valid decimal").
// buildStringField runs every string flag through it
// (09-flagutil-unquote.patch).
func unquoteJSONString(val string) string {
	if len(val) < 2 || val[0] != '"' || val[len(val)-1] != '"' {
		return val
	}
	var s string
	if err := json.Unmarshal([]byte(val), &s); err != nil {
		return val
	}
	return s
}

// usageAllowsValue reports whether value is one of the options a flag's usage
// text enumerates, e.g. "Options: pretty, json, yaml, table, toon." or
// "(options: base, ethereum)". ShorthandConfusionHint uses it to tell a
// legitimate `-o json` (a valid --output-format) apart from a shorthand
// mix-up before suggesting the user meant another flag. False when the usage
// lists no options.
func usageAllowsValue(usage, value string) bool {
	if value == "" {
		return false
	}
	idx := strings.Index(strings.ToLower(usage), "options:")
	if idx < 0 {
		return false
	}
	rest := usage[idx+len("options:"):]
	if end := strings.IndexAny(rest, ".)\n"); end >= 0 {
		rest = rest[:end]
	}
	for _, opt := range strings.Split(rest, ",") {
		if strings.TrimSpace(opt) == value {
			return true
		}
	}
	return false
}
